1	// What a policy costs. This module answers one question — given the items on
2	// a policy and the context the policy is written in, what premium does the
3	// customer pay? It knows nothing about scenarios, steps, or the order events
4	// happen in; see claim-office.ts for that. What a policy pays OUT is the
5	// mirror question, answered by coverage.ts.
6	
7	import { roundUpInFavourOfMHPCO } from "./rounding.js";
8	
9	export interface Customer {
10	  yearsWithMHPCO: number;
11	}
12	
13	const PROCESSING_FEE = 5;
14	const BASE_PREMIUM_BY_TYPE = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	} as const satisfies Record<string, number>;
22	
23	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
24	
25	export interface Item {
26	  type: KnownItemType;
27	  material?: string;
28	  enchantment?: number;
29	  cursed?: boolean;
30	}
31	
32	const FIRST_INSURANCE_SURCHARGE = 0.1;
33	
34	// The MHPCO's price list is closed: an item whose type is absent from it has
35	// no premium and no insurance value, so the quote is refused rather than
36	// guessed at. The type reaches here from parsed JSON, so the compiler's
37	// KnownItemType narrowing is not enough on its own.
38	const basePremiumOf = (item: Item): number => {
39	  const basePremium: number | undefined = BASE_PREMIUM_BY_TYPE[item.type];
40	  if (basePremium === undefined) {
41	    throw new Error(`quote names a ${item.type}, which the MHPCO does not insure`);
42	  }
43	  return basePremium;
44	};
45	
46	const BLOCK_SIZE = 3;
47	const BLOCK_BASE_PREMIUM = 60;
48	
49	const groupByType = (items: Item[]): Item[][] => [
50	  ...items
51	    .reduce(
52	      (groups, item) =>
53	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
54	      new Map<KnownItemType, Item[]>(),
55	    )
56	    .values(),
57	];
58	
59	const sumOfBasePremiums = (items: Item[]): number =>
60	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
61	
62	// Exactly three alike components form a block at a reduced premium; any
63	// other count is priced per item.
64	//
65	// Deliberate simplification: "component" is not yet enforced, so three alike
66	// swords would also get the block. No test covers it and the spec gives no
67	// example — revisit when one does.
68	const groupBasePremiumOf = (group: Item[]): number =>
69	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
70	
71	const policyBasePremiumOf = (items: Item[]): number =>
72	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
73	
74	const CURSE_SURCHARGE = 0.5;
75	
76	// Item-specific modifiers are charged as a percentage of the affected item's
77	// OWN base premium. See withPolicyWideModifiers for the other scope.
78	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
79	  basePremiumOf(item) * rate;
80	
81	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	
84	const isHighlyEnchanted = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
86	
87	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
88	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
89	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
90	];
91	
92	// Every modifier rate in this domain combines additively, whether item-scoped
93	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
94	const combinedRate = (rates: number[]): number =>
95	  rates.reduce((total, rate) => total + rate, 0);
96	
97	// Both item modifiers can apply at once, and they stack additively: a cursed
98	// item with enchantment 5 pays 50 % + 30 % of its base premium.
99	const surchargeRateOn = (item: Item): number =>
100	  combinedRate(
101	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
102	      ({ rate }) => rate,
103	    ),
104	  );
105	
106	const surchargeOn = (item: Item): number =>
107	  shareOfOwnBasePremium(item, surchargeRateOn(item));
108	
109	const itemSurchargesOf = (items: Item[]): number =>
110	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
111	
112	// Policy-wide modifiers scale the whole policy base premium, unlike item
113	// modifiers which are charged against the affected item's own base premium.
114	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
115	// its base — not 110 % × 80 %.
116	const LOYALTY_DISCOUNT = -0.2;
117	const LOYALTY_THRESHOLD_YEARS = 2;
118	
119	const isLoyal = (customer: Customer): boolean =>
120	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
121	
122	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
123	
124	// Everything about the policy's context that shifts its rates, as opposed to
125	// the items being priced. Travels as one value because every policy-wide
126	// modifier reads from it.
127	export interface PolicyContext {
128	  customer: Customer;
129	  isFollowUpContract: boolean;
130	}
131	
132	const policyWideModifierRatesFor = ({
133	  customer,
134	  isFollowUpContract,
135	}: PolicyContext): number[] => [
136	  FIRST_INSURANCE_SURCHARGE,
137	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
138	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
139	];
140	
141	const withPolicyWideModifiers = (
142	  policyBase: number,
143	  policy: PolicyContext,
144	): number =>
145	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
146	
147	export const premiumFor = (items: Item[], policy: PolicyContext): number =>
148	  roundUpInFavourOfMHPCO(
149	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
150	      itemSurchargesOf(items) +
151	      PROCESSING_FEE,
152	  );
153

1	// What a policy covers, and what it pays out. The mirror image of pricing.ts:
2	// that module answers what the customer pays us, this one answers what we pay
3	// the customer. Both are asked by claim-office.ts, which knows the order the
4	// questions come in; neither knows anything about scenarios or steps.
5	
6	import { type Item, type KnownItemType } from "./pricing.js";
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	// What an item is insured FOR, as opposed to what insuring it costs. Payout
14	// caps are derived from these; premiums are not.
15	const INSURANCE_VALUE_BY_TYPE: Record<KnownItemType, number> = {
16	  sword: 1000,
17	  amulet: 600,
18	  staff: 800,
19	  potion: 400,
20	  rune: 250,
21	  moonstone: 250,
22	};
23	
24	const insuranceSumOf = (items: Item[]): number =>
25	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
26	
27	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
28	
29	// A policy pays out at most twice what its items are insured for. Premium
30	// modifiers — curses, enchantments, block discounts — shift what the policy
31	// COSTS and never what it COVERS, so the cap reads insurance values only.
32	export const capFor = (items: Item[]): number =>
33	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
34	
35	// What a claim actually pays, once the policy's own limit is consulted. The
36	// cap is a running total: a policy pays out at most twice its insurance sum
37	// ACROSS all its claims, so each settlement both reads the cap left to it and
38	// reports what remains for the next one.
39	//
40	// Lives here beside capFor rather than in the orchestrator: establishing the
41	// limit and enforcing it are one rule, and claim-office.ts is only meant to
42	// know the order the questions come in, not the answers.
43	export interface Settlement {
44	  payout: number;
45	  remainingCap: number;
46	}
47	
48	export const settleClaim = (
49	  grossPayout: number,
50	  remainingCap: number,
51	): Settlement => {
52	  const payout = Math.min(grossPayout, remainingCap);
53	  return { payout, remainingCap: remainingCap - payout };
54	};
55	
56	const DEDUCTIBLE_PER_DAMAGE = 100;
57	
58	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
59	const HALF_REIMBURSEMENT_SHARE = 0.5;
60	
61	const FULL_REIMBURSEMENT_SHARE = 1;
62	
63	// Named for the clause it gates rather than for a degree of enchantment:
64	// pricing.ts has its own, LOWER enchantment threshold (>= 5, a premium
65	// surcharge), and the two are easy to confuse when both read as adjectives.
66	const qualifiesForHalfReimbursement = (item: Item): boolean =>
67	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
68	
69	// The reimbursement clauses in the order the MHPCO applies them: the FIRST
70	// matching clause decides the share, later ones never override it. Order is
71	// the whole content of the rule, so the list is written out even though the
72	// dragon clause and the default agree — see the note below.
73	//
74	// Half reimbursement: the MHPCO holds that a strongly enchanted item's magic
75	// bears part of its own misfortune.
76	const REIMBURSEMENT_CLAUSES: {
77	  applies: (item: Item) => boolean;
78	  share: number;
79	}[] = [
80	  { applies: qualifiesForHalfReimbursement, share: HALF_REIMBURSEMENT_SHARE },
81	  { applies: () => true, share: FULL_REIMBURSEMENT_SHARE },
82	];
83	
84	// Deliberately ABSENT: the spec's "dragon material => full reimbursement"
85	// clause, which would sit above the half clause. It is unwritten because it is
86	// untestable from the spec's examples — full reimbursement is also the default,
87	// so every dragon example yields the same payout with or without it. The one
88	// case that WOULD distinguish the two orderings, a dragon item with
89	// enchantment >= 8, is fixed by example at HALF (see the enchantment-9 test),
90	// which is the opposite of what a dragon-first clause would pay. So the spec's
91	// own examples contradict placing a dragon clause first, and no example
92	// justifies placing it anywhere else. Adding one here would be guesswork
93	// dressed as fidelity; `material` stays unread until an example forces it.
94	
95	const reimbursementShareFor = (item: Item): number =>
96	  REIMBURSEMENT_CLAUSES.find(({ applies }) => applies(item))?.share ??
97	  FULL_REIMBURSEMENT_SHARE;
98	
99	const reimbursementFor = (item: Item, damage: Damage): number =>
100	  damage.amount * reimbursementShareFor(item);
101	
102	// The customer bears the first 100 G of each damage entry separately, so two
103	// damaged swords carry two deductibles rather than one. The deductible comes
104	// off AFTER the reimbursement clauses have reduced the amount.
105	//
106	// Named for the single subtraction it performs, not for the final payout: this
107	// result is not floored at zero, and the policy's remaining cap is applied
108	// later by settleClaim rather than here. Flooring is still it.todo() in the
109	// spec ("exhausts the cap across successive claims"); until an example forces
110	// it, the name must not claim a settlement this does not compute.
111	const netOfDeductible = (item: Item, damage: Damage): number =>
112	  reimbursementFor(item, damage) - DEDUCTIBLE_PER_DAMAGE;
113	
114	// Every way a claim can be refused, phrased the same way: "claim ..." followed
115	// by what is wrong with it. The MHPCO rejects claims for several unrelated
116	// reasons, but a rejection always reads as a statement about the claim, so the
117	// prefix is written once here rather than at each throw site.
118	export const claimRejection = (reason: string): Error =>
119	  new Error(`claim ${reason}`);
120	
121	// Two different ways a damage can fail to find an insured item, which the
122	// MHPCO rejects for two different reasons. A policy that insures no amulet at
123	// all does not "cover more amulet damages than it insures" — it covers none,
124	// and the claim names an item the customer never brought in. Telling them
125	// apart needs the policy's ORIGINAL items, not just the ones still unclaimed.
126	const uninsuredTypeError = (itemType: string): Error =>
127	  claimRejection(`names a ${itemType}, which the policy does not insure`);
128	
129	const overClaimedTypeError = (itemType: string): Error =>
130	  claimRejection(`covers more ${itemType} damages than the policy insures`);
131	
132	const unmatchedDamageError = (insured: Item[], itemType: string): Error =>
133	  insured.some((item) => item.type === itemType)
134	    ? overClaimedTypeError(itemType)
135	    : uninsuredTypeError(itemType);
136	
137	// Which insured item a damage entry is paid against. A damage names its item
138	// by type only, so the first insured item of that type answers it — but each
139	// insured item is damaged at most once per claim, so a matched item is removed
140	// from those still available. Two sword damages need two insured swords.
141	const takeDamagedItem = (
142	  insured: Item[],
143	  available: Item[],
144	  damage: Damage,
145	): { item: Item; remaining: Item[] } => {
146	  const index = available.findIndex((item) => item.type === damage.itemType);
147	  if (index === -1) {
148	    throw unmatchedDamageError(insured, damage.itemType);
149	  }
150	  return {
151	    item: available[index],
152	    remaining: available.filter((_, at) => at !== index),
153	  };
154	};
155	
156	// Each damage paired with the insured item it is settled against. Separated
157	// from the summing below because pairing and arithmetic are two rules: which
158	// item answers a damage is a matching question, what that pair pays is not.
159	// This is also where an unmatched damage is rejected, so payoutForDamages sees
160	// only pairs it can price.
161	interface SettledPair {
162	  item: Item;
163	  damage: Damage;
164	}
165	
166	const pairDamagesWithItems = (
167	  items: Item[],
168	  damages: Damage[],
169	): SettledPair[] =>
170	  damages.reduce<{ pairs: SettledPair[]; available: Item[] }>(
171	    ({ pairs, available }, damage) => {
172	      const { item, remaining } = takeDamagedItem(items, available, damage);
173	      return { pairs: [...pairs, { item, damage }], available: remaining };
174	    },
175	    { pairs: [], available: items },
176	  ).pairs;
177	
178	// A damage is a loss, never a gain: a negative amount would pay the MHPCO's
179	// own money back into the policy's cap, so the claim is rejected outright.
180	const rejectNegativeAmounts = (damages: Damage[]): void => {
181	  for (const { itemType, amount } of damages) {
182	    if (amount < 0) {
183	      throw claimRejection(
184	        `reports a negative ${itemType} damage of ${amount}`,
185	      );
186	    }
187	  }
188	};
189	
190	export const payoutForDamages = (items: Item[], damages: Damage[]): number => {
191	  rejectNegativeAmounts(damages);
192	  return pairDamagesWithItems(items, damages).reduce(
193	    (total, { item, damage }) => total + netOfDeductible(item, damage),
194	    0,
195	  );
196	};
197

1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import {
7	  capFor,
8	  claimRejection,
9	  payoutForDamages,
10	  settleClaim,
11	  type Damage,
12	} from "./coverage.js";
13	
14	export type { Customer, KnownItemType } from "./pricing.js";
15	export type { Damage } from "./coverage.js";
16	
17	export interface Scenario {
18	  customer: Customer;
19	  steps: Step[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: { cause: string; damages: Damage[] };
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface ScenarioResults {
36	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
37	}
38	
39	// What earlier steps have established by the time a later step is priced.
40	// Steps are not independent: a quote is a follow-up contract when the customer
41	// already took a quote earlier in the same scenario. Folding this forward —
42	// rather than re-deriving it from the step prefix — is what lets a step read
43	// the state its predecessors left behind.
44	interface Policy {
45	  // The insured items, kept because a claim is settled against them: what a
46	  // damage reimburses depends on the item's own material and enchantment, not
47	  // on the damage entry alone.
48	  items: Item[];
49	  remainingCap: number;
50	}
51	
52	interface ScenarioState {
53	  hasQuoted: boolean;
54	  // Keyed by the step index of the quote that created the policy, which is
55	  // how a later claim step refers to it.
56	  policies: Map<number, Policy>;
57	}
58	
59	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
60	
61	type StepOutcome = ScenarioResults["results"][number];
62	
63	interface StepRun {
64	  outcome: StepOutcome;
65	  state: ScenarioState;
66	}
67	
68	// Every policy a step establishes is recorded the same way, so both handlers
69	// go through here rather than each rebuilding the map.
70	const withPolicy = (
71	  state: ScenarioState,
72	  index: number,
73	  policy: Policy,
74	): ScenarioState => ({
75	  ...state,
76	  policies: new Map(state.policies).set(index, policy),
77	});
78	
79	const runQuote = (
80	  { items }: QuoteStep,
81	  customer: Customer,
82	  state: ScenarioState,
83	  index: number,
84	): StepRun => ({
85	  outcome: {
86	    premium: premiumFor(items, {
87	      customer,
88	      isFollowUpContract: state.hasQuoted,
89	    }),
90	  },
91	  state: withPolicy({ ...state, hasQuoted: true }, index, {
92	    items,
93	    remainingCap: capFor(items),
94	  }),
95	});
96	
97	const runClaim = (
98	  { policy: policyIndex, incident }: ClaimStep,
99	  state: ScenarioState,
100	): StepRun => {
101	  // A claim always names a policy an earlier quote step created. No spec
102	  // example covers a claim naming a step that never quoted, so this is not the
103	  // considered answer to that question — but the previous fallback of an empty
104	  // policy was worse than none: it returned a payout of 0 with 0 cap left,
105	  // which is indistinguishable from a real policy that has exhausted its cap.
106	  // A typo'd index read as a legitimate settlement. Fail loudly instead until
107	  // an example says otherwise.
108	  const policy = state.policies.get(policyIndex);
109	  if (policy === undefined) {
110	    throw claimRejection(`names policy ${policyIndex}, which no step created`);
111	  }
112	  const { payout, remainingCap } = settleClaim(
113	    payoutForDamages(policy.items, incident.damages),
114	    policy.remainingCap,
115	  );
116	
117	  return {
118	    outcome: { payout, remainingCap },
119	    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
120	  };
121	};
122	
123	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
124	// so that adding a step kind to the Step union turns "I forgot to handle it"
125	// into a compile error rather than a wrong number.
126	const runStep = (
127	  step: Step,
128	  customer: Customer,
129	  state: ScenarioState,
130	  index: number,
131	): StepRun => {
132	  switch (step.op) {
133	    case "quote":
134	      return runQuote(step, customer, state, index);
135	    case "claim":
136	      return runClaim(step, state);
137	  }
138	};
139	
140	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
141	  const { results } = steps.reduce<{
142	    results: StepOutcome[];
143	    state: ScenarioState;
144	  }>(
145	    ({ results, state }, step, index) => {
146	      const stepRun = runStep(step, customer, state, index);
147	      return { results: [...results, stepRun.outcome], state: stepRun.state };
148	    },
149	    { results: [], state: INITIAL_STATE },
150	  );
151	
152	  return { results };
153	};
